/* BIP 327's test vectors through the pinned secp256k1-zkp, by the public
 * calls the signing engine makes (core/signing/signing.c): key aggregation
 * in the given order (the engine never sorts), the x-only tweak, nonce
 * generation, nonce aggregation and processing, partial signing and its
 * verification, and signature aggregation, with the final signature checked
 * by BIP 340.
 *
 * The vectors are the library's own copy of BIP 327's JSON files
 * (src/modules/musig/vectors.h at the pinned commit, generated by its
 * contrib/musig2-vectors.py), so they move with the pin. Two things the
 * public calls cannot do, the vectors need: a secret nonce given as bytes
 * (the sign vectors fix it) and a key-aggregation cache made from an
 * aggregate key alone (one nonce-generation vector). The first is built here
 * in the pinned commit's layout of secp256k1_musig_secnonce (4 magic bytes,
 * k1, k2, the 64-byte public key), which the test checks against what
 * secp256k1_musig_nonce_gen produces before it relies on it; the second case
 * is checked as far as the public calls reach (its public nonce from the
 * same inputs with a real cache differs, as it must). The vector that signs
 * with a key not among the aggregated ones is skipped, as the library's own
 * test skips it: the library does not refuse it. */
#include <secp256k1.h>
#include <secp256k1_extrakeys.h>
#include <secp256k1_musig.h>
#include <secp256k1_schnorrsig.h>
#include <stdio.h>
#include <string.h>
#include "modules/musig/vectors.h"
#include "../check.h"

#define MAX_KEYS 8

static secp256k1_context *ctx;
static int illegal;
static void on_illegal(const char *msg, void *data) { (void)msg; (void)data; illegal++; }

/* The engine's key aggregation: the keys in the order given, then tweaks. */
static int agg(enum MUSIG_ERROR *error, secp256k1_musig_keyagg_cache *cache, unsigned char *agg32,
               const unsigned char pubkeys[][33], const unsigned char tweaks[][32], size_t n, const size_t *idx,
               size_t nt, const size_t *tidx, const int *xonly)
{
    secp256k1_pubkey pk[MAX_KEYS], out;
    const secp256k1_pubkey *ptr[MAX_KEYS];
    secp256k1_xonly_pubkey x;
    for (size_t i = 0; i < n; i++) {
        if (!secp256k1_ec_pubkey_parse(ctx, &pk[i], pubkeys[idx[i]], 33)) { *error = MUSIG_PUBKEY; return 0; }
        ptr[i] = &pk[i];
    }
    if (!secp256k1_musig_pubkey_agg(ctx, NULL, NULL, cache, ptr, n)) { *error = MUSIG_OTHER; return 0; }
    for (size_t i = 0; i < nt; i++) {
        int ok = xonly[i] ? secp256k1_musig_pubkey_xonly_tweak_add(ctx, NULL, cache, tweaks[tidx[i]])
                          : secp256k1_musig_pubkey_ec_tweak_add(ctx, NULL, cache, tweaks[tidx[i]]);
        if (!ok) { *error = MUSIG_TWEAK; return 0; }
    }
    if (!secp256k1_musig_pubkey_get(ctx, &out, cache) || !secp256k1_xonly_pubkey_from_pubkey(ctx, &x, NULL, &out)) {
        *error = MUSIG_OTHER; return 0;
    }
    if (agg32 && !secp256k1_xonly_pubkey_serialize(ctx, agg32, &x)) { *error = MUSIG_OTHER; return 0; }
    return 1;
}

/* A secret nonce from its 64 bytes (k1, k2) for `pubkey`, in the pinned
 * layout; `layout_ok` says the layout was confirmed against nonce_gen. */
static int layout_ok;
static unsigned char magic[4];
static void set_secnonce(secp256k1_musig_secnonce *sn, const unsigned char *k64, const secp256k1_pubkey *pubkey)
{
    memset(sn, 0, sizeof *sn);
    memcpy(sn->data, magic, 4);
    memcpy(sn->data + 4, k64, 64);
    memcpy(sn->data + 68, pubkey->data, 64);
}

static void check_layout(void)
{
    secp256k1_musig_secnonce sn;
    secp256k1_musig_pubnonce pn;
    secp256k1_keypair kp;
    secp256k1_pubkey pk;
    unsigned char sk[32], rnd[32];
    memset(sk, 0x31, 32); memset(rnd, 0x42, 32);
    CHECK(secp256k1_keypair_create(ctx, &kp, sk) && secp256k1_keypair_pub(ctx, &pk, &kp));
    CHECK(secp256k1_musig_nonce_gen(ctx, &sn, &pn, rnd, sk, &pk, NULL, NULL, NULL));
    CHECK(sizeof sn.data == 132);
    memcpy(magic, sn.data, 4);
    layout_ok = memcmp(sn.data + 68, pk.data, 64) == 0 && sizeof sn.data == 132;
    CHECK(layout_ok);
}

static void test_keyagg(void)
{
    const struct musig_key_agg_vector *v = &musig_key_agg_vector;
    for (size_t i = 0; i < sizeof v->valid_case / sizeof v->valid_case[0]; i++) {
        const struct musig_key_agg_valid_test_case *c = &v->valid_case[i];
        enum MUSIG_ERROR e;
        secp256k1_musig_keyagg_cache cache;
        unsigned char a[32];
        CHECK(agg(&e, &cache, a, v->pubkeys, v->tweaks, c->key_indices_len, c->key_indices, 0, NULL, NULL));
        CHECK(memcmp(a, c->expected, 32) == 0);
    }
    for (size_t i = 0; i < sizeof v->error_case / sizeof v->error_case[0]; i++) {
        const struct musig_key_agg_error_test_case *c = &v->error_case[i];
        enum MUSIG_ERROR e = MUSIG_OTHER;
        secp256k1_musig_keyagg_cache cache;
        CHECK(!agg(&e, &cache, NULL, v->pubkeys, v->tweaks, c->key_indices_len, c->key_indices, c->tweak_indices_len, c->tweak_indices, c->is_xonly));
        CHECK(e == c->error);
    }
}

static void test_noncegen(void)
{
    const struct musig_nonce_gen_vector *v = &musig_nonce_gen_vector;
    for (size_t i = 0; i < sizeof v->test_case / sizeof v->test_case[0]; i++) {
        const struct musig_nonce_gen_test_case *c = &v->test_case[i];
        secp256k1_musig_secnonce sn;
        secp256k1_musig_pubnonce pn;
        secp256k1_pubkey pk;
        unsigned char p66[66];
        CHECK(secp256k1_ec_pubkey_parse(ctx, &pk, c->pk, 33));
        if (c->has_aggpk) {
            /* a cache from an aggregate key alone is not a public call: the same inputs
             * with no cache must give another nonce (the cache is an input) */
            CHECK(secp256k1_musig_nonce_gen(ctx, &sn, &pn, c->rand_, c->has_sk ? c->sk : NULL, &pk,
                                            c->has_msg ? c->msg : NULL, NULL, c->has_extra_in ? c->extra_in : NULL));
            CHECK(secp256k1_musig_pubnonce_serialize(ctx, p66, &pn) && memcmp(p66, c->expected_pubnonce, 66) != 0);
            continue;
        }
        CHECK(secp256k1_musig_nonce_gen(ctx, &sn, &pn, c->rand_, c->has_sk ? c->sk : NULL, &pk,
                                        c->has_msg ? c->msg : NULL, NULL, c->has_extra_in ? c->extra_in : NULL));
        CHECK(memcmp(sn.data + 4, c->expected_secnonce, 64) == 0 && memcmp(sn.data + 68, pk.data, 64) == 0);
        CHECK(secp256k1_musig_pubnonce_serialize(ctx, p66, &pn) && memcmp(p66, c->expected_pubnonce, 66) == 0);
    }
}

static void test_nonceagg(void)
{
    const struct musig_nonce_agg_vector *v = &musig_nonce_agg_vector;
    for (size_t i = 0; i < sizeof v->valid_case / sizeof v->valid_case[0]; i++) {
        const struct musig_nonce_agg_test_case *c = &v->valid_case[i];
        secp256k1_musig_pubnonce pn[2];
        const secp256k1_musig_pubnonce *ptr[2];
        secp256k1_musig_aggnonce an;
        unsigned char a66[66];
        for (int j = 0; j < 2; j++) { CHECK(secp256k1_musig_pubnonce_parse(ctx, &pn[j], v->pnonces[c->pnonce_indices[j]])); ptr[j] = &pn[j]; }
        CHECK(secp256k1_musig_nonce_agg(ctx, &an, ptr, 2) && secp256k1_musig_aggnonce_serialize(ctx, a66, &an));
        CHECK(memcmp(a66, c->expected, 66) == 0);
    }
    for (size_t i = 0; i < sizeof v->error_case / sizeof v->error_case[0]; i++) {
        const struct musig_nonce_agg_test_case *c = &v->error_case[i];
        secp256k1_musig_pubnonce pn;
        for (int j = 0; j < 2; j++)
            CHECK((c->invalid_nonce_idx != j) == secp256k1_musig_pubnonce_parse(ctx, &pn, v->pnonces[c->pnonce_indices[j]]));
    }
}

static void test_signverify(void)
{
    const struct musig_sign_verify_vector *v = &musig_sign_verify_vector;
    secp256k1_keypair kp;
    secp256k1_pubkey pk0;
    CHECK(secp256k1_keypair_create(ctx, &kp, v->sk) && secp256k1_ec_pubkey_parse(ctx, &pk0, v->pubkeys[0], 33));
    for (size_t i = 0; layout_ok && i < sizeof v->valid_case / sizeof v->valid_case[0]; i++) {
        const struct musig_valid_case *c = &v->valid_case[i];
        enum MUSIG_ERROR e;
        secp256k1_musig_keyagg_cache cache;
        secp256k1_musig_aggnonce an;
        secp256k1_musig_session s;
        secp256k1_musig_secnonce sn;
        secp256k1_musig_partial_sig ps;
        secp256k1_musig_pubnonce pn;
        unsigned char p32[32];
        CHECK(agg(&e, &cache, NULL, v->pubkeys, NULL, c->key_indices_len, c->key_indices, 0, NULL, NULL));
        CHECK(secp256k1_musig_aggnonce_parse(ctx, &an, v->aggnonces[c->aggnonce_index]));
        CHECK(secp256k1_musig_nonce_process(ctx, &s, &an, v->msgs[c->msg_index], &cache, NULL));
        set_secnonce(&sn, v->secnonces[0], &pk0);
        CHECK(secp256k1_musig_partial_sign(ctx, &ps, &sn, &kp, &cache, &s) && secp256k1_musig_partial_sig_serialize(ctx, p32, &ps));
        CHECK(memcmp(p32, c->expected, 32) == 0);
        CHECK(memcmp(sn.data, (unsigned char[132]){0}, 132) == 0);          /* the library zeroed the secret it used */
        CHECK(secp256k1_musig_pubnonce_parse(ctx, &pn, v->pubnonces[0]) && secp256k1_musig_partial_sig_verify(ctx, &ps, &pn, &pk0, &cache, &s));
    }
    for (size_t i = 1; layout_ok && i < sizeof v->sign_error_case / sizeof v->sign_error_case[0]; i++) {
        const struct musig_sign_error_case *c = &v->sign_error_case[i];
        enum MUSIG_ERROR e = MUSIG_OTHER;
        secp256k1_musig_keyagg_cache cache;
        secp256k1_musig_aggnonce an;
        secp256k1_musig_session s;
        secp256k1_musig_secnonce sn;
        secp256k1_musig_partial_sig ps;
        int ok = agg(&e, &cache, NULL, v->pubkeys, NULL, c->key_indices_len, c->key_indices, 0, NULL, NULL);
        CHECK(ok == (c->error != MUSIG_PUBKEY) && (ok || e == c->error));
        if (!ok) continue;
        ok = secp256k1_musig_aggnonce_parse(ctx, &an, v->aggnonces[c->aggnonce_index]);
        CHECK(ok == (c->error != MUSIG_AGGNONCE));
        if (!ok) continue;
        CHECK(secp256k1_musig_nonce_process(ctx, &s, &an, v->msgs[c->msg_index], &cache, NULL));
        set_secnonce(&sn, v->secnonces[c->secnonce_index], &pk0);
        int before = illegal;
        ok = secp256k1_musig_partial_sign(ctx, &ps, &sn, &kp, &cache, &s);
        if (c->error == MUSIG_SECNONCE) CHECK(!ok && illegal == before + 1);   /* refused through the illegal-argument callback */
        else CHECK(ok && illegal == before);
    }
    for (size_t i = 0; i < sizeof v->verify_fail_case / sizeof v->verify_fail_case[0]; i++) {
        const struct musig_verify_fail_error_case *c = &v->verify_fail_case[i];
        enum MUSIG_ERROR e;
        secp256k1_musig_keyagg_cache cache;
        secp256k1_musig_aggnonce an;
        secp256k1_musig_session s;
        secp256k1_musig_partial_sig ps;
        secp256k1_musig_pubnonce pn[3];
        const secp256k1_musig_pubnonce *ptr[3];
        secp256k1_pubkey pk;
        int ok;
        CHECK(c->nonce_indices_len <= 3);
        for (size_t j = 0; j < c->nonce_indices_len; j++) { CHECK(secp256k1_musig_pubnonce_parse(ctx, &pn[j], v->pubnonces[c->nonce_indices[j]])); ptr[j] = &pn[j]; }
        CHECK(agg(&e, &cache, NULL, v->pubkeys, NULL, c->key_indices_len, c->key_indices, 0, NULL, NULL));
        CHECK(secp256k1_musig_nonce_agg(ctx, &an, ptr, c->nonce_indices_len));
        CHECK(secp256k1_musig_nonce_process(ctx, &s, &an, v->msgs[c->msg_index], &cache, NULL));
        CHECK(secp256k1_ec_pubkey_parse(ctx, &pk, v->pubkeys[c->signer_index], 33));
        ok = secp256k1_musig_partial_sig_parse(ctx, &ps, c->sig);
        CHECK(ok == (c->error != MUSIG_SIG));
        if (!ok) continue;
        CHECK(secp256k1_musig_partial_sig_verify(ctx, &ps, &pn[0], &pk, &cache, &s) == (c->error != MUSIG_SIG_VERIFY));
    }
    for (size_t i = 0; i < sizeof v->verify_error_case / sizeof v->verify_error_case[0]; i++) {
        const struct musig_verify_fail_error_case *c = &v->verify_error_case[i];
        enum MUSIG_ERROR e = MUSIG_OTHER;
        secp256k1_musig_keyagg_cache cache;
        secp256k1_musig_pubnonce pn;
        int ok = agg(&e, &cache, NULL, v->pubkeys, NULL, c->key_indices_len, c->key_indices, 0, NULL, NULL);
        CHECK(ok == (c->error != MUSIG_PUBKEY) && (ok || e == c->error));
        if (!ok) continue;
        CHECK(secp256k1_musig_pubnonce_parse(ctx, &pn, v->pubnonces[c->nonce_indices[c->signer_index]]) == (c->error != MUSIG_PUBNONCE));
    }
}

static void test_tweak(void)
{
    const struct musig_tweak_vector *v = &musig_tweak_vector;
    secp256k1_pubkey pk0;
    secp256k1_musig_aggnonce an;
    secp256k1_keypair kp;
    CHECK(secp256k1_musig_aggnonce_parse(ctx, &an, v->aggnonce) && secp256k1_ec_pubkey_parse(ctx, &pk0, v->pubkeys[0], 33));
    CHECK(secp256k1_keypair_create(ctx, &kp, v->sk));
    for (size_t i = 0; layout_ok && i < sizeof v->valid_case / sizeof v->valid_case[0]; i++) {
        const struct musig_tweak_case *c = &v->valid_case[i];
        enum MUSIG_ERROR e;
        secp256k1_musig_keyagg_cache cache;
        secp256k1_musig_session s;
        secp256k1_musig_secnonce sn;
        secp256k1_musig_partial_sig ps;
        secp256k1_musig_pubnonce pn;
        unsigned char p32[32];
        CHECK(agg(&e, &cache, NULL, v->pubkeys, v->tweaks, c->key_indices_len, c->key_indices, c->tweak_indices_len, c->tweak_indices, c->is_xonly));
        CHECK(secp256k1_musig_nonce_process(ctx, &s, &an, v->msg, &cache, NULL));
        set_secnonce(&sn, v->secnonce, &pk0);
        CHECK(secp256k1_musig_partial_sign(ctx, &ps, &sn, &kp, &cache, &s) && secp256k1_musig_partial_sig_serialize(ctx, p32, &ps));
        CHECK(memcmp(p32, c->expected, 32) == 0);
        CHECK(secp256k1_musig_pubnonce_parse(ctx, &pn, v->pubnonces[c->nonce_indices[c->signer_index]]));
        CHECK(secp256k1_musig_partial_sig_verify(ctx, &ps, &pn, &pk0, &cache, &s));
    }
    for (size_t i = 0; i < sizeof v->error_case / sizeof v->error_case[0]; i++) {
        const struct musig_tweak_case *c = &v->error_case[i];
        enum MUSIG_ERROR e = MUSIG_OTHER;
        secp256k1_musig_keyagg_cache cache;
        CHECK(!agg(&e, &cache, NULL, v->pubkeys, v->tweaks, c->key_indices_len, c->key_indices, c->tweak_indices_len, c->tweak_indices, c->is_xonly));
        CHECK(e == MUSIG_TWEAK);
    }
}

static void test_sigagg(void)
{
    const struct musig_sig_agg_vector *v = &musig_sig_agg_vector;
    enum { NPS = sizeof v->psigs / sizeof v->psigs[0] };
    for (size_t i = 0; i < sizeof v->valid_case / sizeof v->valid_case[0]; i++) {
        const struct musig_sig_agg_case *c = &v->valid_case[i];
        enum MUSIG_ERROR e;
        secp256k1_musig_keyagg_cache cache;
        secp256k1_musig_aggnonce an;
        secp256k1_musig_session s;
        secp256k1_musig_partial_sig ps[NPS];
        const secp256k1_musig_partial_sig *ptr[NPS];
        secp256k1_xonly_pubkey ak;
        unsigned char a32[32], sig[64];
        CHECK(agg(&e, &cache, a32, v->pubkeys, v->tweaks, c->key_indices_len, c->key_indices, c->tweak_indices_len, c->tweak_indices, c->is_xonly));
        CHECK(secp256k1_musig_aggnonce_parse(ctx, &an, c->aggnonce) && secp256k1_musig_nonce_process(ctx, &s, &an, v->msg, &cache, NULL));
        for (size_t j = 0; j < c->psig_indices_len; j++) { CHECK(secp256k1_musig_partial_sig_parse(ctx, &ps[j], v->psigs[c->psig_indices[j]])); ptr[j] = &ps[j]; }
        CHECK(secp256k1_musig_partial_sig_agg(ctx, sig, &s, ptr, c->psig_indices_len) && memcmp(sig, c->expected, 64) == 0);
        CHECK(secp256k1_xonly_pubkey_parse(ctx, &ak, a32) && secp256k1_schnorrsig_verify(ctx, sig, v->msg, 32, &ak));
        sig[5] ^= 1;
        CHECK(!secp256k1_schnorrsig_verify(ctx, sig, v->msg, 32, &ak));     /* the control */
    }
    for (size_t i = 0; i < sizeof v->error_case / sizeof v->error_case[0]; i++) {
        const struct musig_sig_agg_case *c = &v->error_case[i];
        secp256k1_musig_partial_sig ps;
        for (size_t j = 0; j < c->psig_indices_len; j++)
            CHECK((c->invalid_sig_idx != (int)j) == secp256k1_musig_partial_sig_parse(ctx, &ps, v->psigs[c->psig_indices[j]]));
    }
}

int main(void)
{
    ctx = secp256k1_context_create(SECP256K1_CONTEXT_NONE);
    secp256k1_context_set_illegal_callback(ctx, on_illegal, NULL);
    check_layout();
    test_keyagg();
    test_noncegen();
    test_nonceagg();
    test_signverify();
    test_tweak();
    test_sigagg();
    printf("  BIP 327 vectors: key aggregation, nonce generation and aggregation, signing and verification, tweaks, signature aggregation\n");
    printf("  illegal-argument callbacks: %d (one expected: the invalid secret nonce)\n", illegal);
    secp256k1_context_destroy(ctx);
    return check_done();
}
